function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function isValidPhone(v) {
  return /^01[0125][0-9]{8}$/.test((v || "").replace(/\D/g, ""));
}
function fmtMoney(n) {
  const v = Number(n) || 0;
  return v.toLocaleString("en-US") + " جنيه";
}

function flattenCategories(categories, parentId = null, depth = 0) {
  const out = [];
  categories
    .filter((c) => (c.parentId || null) === parentId)
    .forEach((c) => {
      out.push({ ...c, depth });
      out.push(...flattenCategories(categories, c.id, depth + 1));
    });
  return out;
}

function categoryDescendantIds(categories, id) {
  const kids = categories.filter((c) => c.parentId === id).map((c) => c.id);
  return kids.reduce((acc, k) => acc.concat(k, categoryDescendantIds(categories, k)), []);
}

async function safeGet(key, shared, fallback) {
  try {
    const r = await window.storage.get(key, shared);
    if (!r) return fallback;
    return JSON.parse(r.value);
  } catch (e) {
    return fallback;
  }
}
async function safeSet(key, value, shared) {
  try {
    await window.storage.set(key, JSON.stringify(value), shared);
    return true;
  } catch (e) {
    return false;
  }
}

