function Btn({ variant = "solid", children, style, ...props }) {
  const base = {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    borderRadius: 999,
    padding: "11px 22px",
    fontSize: 14,
    fontWeight: 700,
    cursor: "pointer",
    border: "none",
    transition: "transform .15s ease, opacity .15s ease",
    fontFamily: "inherit",
  };
  const variants = {
    solid: { background: C.green, color: C.white },
    orange: { background: C.orange, color: C.white },
    outline: { background: "transparent", color: C.green, border: `1.6px solid ${C.green}` },
    ghost: { background: C.sage, color: C.ink },
    danger: { background: "#C24A3A", color: C.white },
  };
  return (
    <button
      {...props}
      style={{ ...base, ...variants[variant], ...style }}
      onMouseDown={(e) => (e.currentTarget.style.transform = "scale(.97)")}
      onMouseUp={(e) => (e.currentTarget.style.transform = "scale(1)")}
    >
      {children}
    </button>
  );
}

function Modal({ onClose, children, width = 420 }) {
  return (
    <div
      style={{
        position: "fixed", inset: 0, background: "rgba(20,25,15,.5)",
        display: "flex", alignItems: "center", justifyContent: "center",
        zIndex: 150, padding: 16,
      }}
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: C.white, borderRadius: 20, width: "100%", maxWidth: width,
          maxHeight: "88vh", overflowY: "auto", padding: 24, position: "relative",
          boxShadow: "0 20px 60px rgba(0,0,0,.3)",
        }}
      >
        <button
          onClick={onClose}
          style={{
            position: "absolute", top: 14, left: 14, background: C.sage,
            border: "none", borderRadius: 999, width: 32, height: 32,
            display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
          }}
        >
          <X size={16} />
        </button>
        {children}
      </div>
    </div>
  );
}

