/* ---------------- Bazaar ---------------- */
function renderMedia(item) {
  const url = item.url || "";
  if (item.type === "video") {
    let ytId = null;
    const m1 = url.match(/youtu\.be\/([^\?&]+)/);
    const m2 = url.match(/[?&]v=([^&]+)/);
    if (m1) ytId = m1[1]; else if (m2) ytId = m2[1];
    if (ytId) {
      return <iframe title="video" src={`https://www.youtube.com/embed/${ytId}`} style={{ width: "100%", height: "100%", border: "none" }} allowFullScreen />;
    }
    if (/\.mp4($|\?)/.test(url)) {
      return <video src={url} controls style={{ width: "100%", height: "100%", objectFit: "cover" }} />;
    }
    return (
      <a href={url} target="_blank" rel="noreferrer" style={{ width: "100%", height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 6, color: C.green, textDecoration: "none", background: C.sage }}>
        <VideoIcon size={26} /> <span style={{ fontSize: 12, fontWeight: 700 }}>شوف الفيديو</span>
      </a>
    );
  }
  return url ? <img src={url} alt={item.caption || ""} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : (
    <div style={{ width: "100%", height: "100%", background: C.sage, display: "flex", alignItems: "center", justifyContent: "center" }}><ImageIcon color={C.leaf} /></div>
  );
}

