/* ---------------- Stats ---------------- */
function useCountUp(target, duration = 1400) {
  const [display, setDisplay] = useState(String(target));
  useEffect(() => {
    const str = String(target);
    const match = str.match(/\d+/);
    if (!match) { setDisplay(str); return; }
    const num = parseInt(match[0], 10);
    const prefix = str.slice(0, match.index);
    const suffix = str.slice(match.index + match[0].length);
    let raf, start;
    function step(ts) {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(eased * num);
      setDisplay(prefix + current.toLocaleString("en-US") + suffix);
      if (progress < 1) raf = requestAnimationFrame(step);
    }
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target]);
  return display;
}

function StatBlock({ value, label }) {
  const display = useCountUp(value);
  return (
    <div style={{ textAlign: "center" }}>
      <div style={{ fontSize: "clamp(30px,5vw,48px)", fontWeight: 800, color: C.orange, fontFamily: "'Changa', sans-serif" }}>{display}</div>
      <div style={{ fontSize: 13, opacity: 0.85, fontWeight: 700, marginTop: 2 }}>{label}</div>
    </div>
  );
}

