/* ---------------- Auth Modal ---------------- */
function AuthModal({ onClose, users, saveUsers, onLoggedIn }) {
  const [tab, setTab] = useState("login");
  const [form, setForm] = useState({ name: "", phone: "", phone2: "", password: "" });
  const [err, setErr] = useState("");

  function handleLogin() {
    if (!isValidPhone(form.phone)) { setErr("اكتب رقم موبايل مصري صحيح (01 وبعده 9 أرقام)"); return; }
    const u = users.find((u) => u.identifier === form.phone && u.password === form.password);
    if (!u) { setErr("البيانات غلط، اتأكد من رقم التليفون والباسورد"); return; }
    onLoggedIn(u);
  }
  async function handleRegister() {
    if (!form.name || !form.phone || !form.password) { setErr("من فضلك املأ كل الحقول"); return; }
    if (!isValidPhone(form.phone)) { setErr("اكتب رقم موبايل مصري صحيح (01 وبعده 9 أرقام)"); return; }
    if (form.phone !== form.phone2) { setErr("رقم التليفون في المرتين مش متطابق، اتأكد وجرب تاني"); return; }
    if (users.some((u) => u.identifier === form.phone)) { setErr("الرقم ده مسجل قبل كده، سجل دخول"); return; }
    const newUser = { id: uid(), name: form.name, identifier: form.phone, password: form.password };
    const updated = [...users, newUser];
    await saveUsers(updated);
    onLoggedIn(newUser);
  }

  return (
    <Modal onClose={onClose}>
      <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
        <button onClick={() => { setTab("login"); setErr(""); }} style={{ flex: 1, padding: 10, borderRadius: 10, border: "none", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, background: tab === "login" ? C.green : C.sage, color: tab === "login" ? "#fff" : C.ink }}>تسجيل دخول</button>
        <button onClick={() => { setTab("register"); setErr(""); }} style={{ flex: 1, padding: 10, borderRadius: 10, border: "none", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, background: tab === "register" ? C.green : C.sage, color: tab === "register" ? "#fff" : C.ink }}>حساب جديد</button>
      </div>
      {tab === "register" && (
        <Field label="الاسم" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="اكتب اسمك" />
      )}
      <Field label="رقم التليفون" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="01xxxxxxxxx" />
      {tab === "register" && (
        <Field label="أعد كتابة رقم التليفون" value={form.phone2} onChange={(e) => setForm({ ...form, phone2: e.target.value })} placeholder="01xxxxxxxxx" />
      )}
      <Field label="الباسورد" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} placeholder="********" />
      {err && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{err}</div>}
      <Btn onClick={tab === "login" ? handleLogin : handleRegister} style={{ width: "100%" }}>
        {tab === "login" ? "دخول" : "إنشاء الحساب"}
      </Btn>
    </Modal>
  );
}

/* ---------------- Checkout Modal ---------------- */
function CheckoutModal({ onClose, currentUser, total, onSubmit, deliveryAreas, minOrder }) {
  const [form, setForm] = useState({ name: currentUser?.name || "", phone: currentUser?.identifier || "", phone2: "", address: "", notes: "", areaId: "" });
  const [err, setErr] = useState("");
  const min = Number(minOrder) || 0;
  const belowMin = min > 0 && total < min;
  const selectedArea = deliveryAreas.find((a) => a.id === form.areaId);
  const deliveryFee = selectedArea && selectedArea.price ? Number(selectedArea.price) : 0;
  const grandTotal = total + deliveryFee;

  function submit() {
    if (!form.name || !form.phone || !form.address) { setErr("من فضلك املأ الاسم ورقم التليفون والعنوان"); return; }
    if (!isValidPhone(form.phone)) { setErr("اكتب رقم موبايل مصري صحيح (01 وبعده 9 أرقام)"); return; }
    if (!currentUser && form.phone !== form.phone2) { setErr("رقم التليفون في المرتين مش متطابق، اتأكد وجرب تاني"); return; }
    if (belowMin) { setErr(`الحد الأدنى للطلب ${fmtMoney(min)}`); return; }
    onSubmit({ ...form, area: selectedArea ? selectedArea.name : "", deliveryFee, total: grandTotal });
  }
  return (
    <Modal onClose={onClose}>
      <div style={{ fontWeight: 800, fontSize: 18, marginBottom: 16 }}>بيانات التوصيل</div>
      <Field label="الاسم بالكامل" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
      <Field label="رقم التليفون" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="01xxxxxxxxx" />
      {!currentUser && (
        <Field label="أعد كتابة رقم التليفون للتأكيد" value={form.phone2} onChange={(e) => setForm({ ...form, phone2: e.target.value })} placeholder="01xxxxxxxxx" />
      )}
      <Field label="العنوان بالتفصيل" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} placeholder="المنطقة، الشارع، رقم العمارة/الدور" />
      {deliveryAreas.length > 0 && (
        <label style={{ display: "block", marginBottom: 12 }}>
          <span style={{ fontSize: 13, color: C.ink, opacity: 0.75, display: "block", marginBottom: 5 }}>منطقة التوصيل</span>
          <select value={form.areaId} onChange={(e) => setForm({ ...form, areaId: e.target.value })} style={{ width: "100%", border: `1.5px solid ${C.line}`, borderRadius: 10, padding: "10px 12px", fontSize: 14, fontFamily: "inherit", background: C.white }}>
            <option value="">اختار منطقتك</option>
            {deliveryAreas.map((a) => (
              <option key={a.id} value={a.id}>{a.name}{a.price ? ` (+${fmtMoney(a.price)})` : " (السعر هيتأكد تليفونيًا)"}</option>
            ))}
          </select>
        </label>
      )}
      <TextAreaField label="ملاحظات (اختياري)" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="أي تفاصيل تانية عايز تقولها" />
      {belowMin && (
        <div style={{ background: C.sage, borderRadius: 10, padding: "10px 12px", fontSize: 13, marginBottom: 12, color: C.ink }}>
          الحد الأدنى للطلب <b>{fmtMoney(min)}</b> — ناقصك {fmtMoney(min - total)}
        </div>
      )}
      {err && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{err}</div>}
      <div style={{ borderTop: `1px solid ${C.line}`, paddingTop: 10, marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, opacity: 0.75, marginBottom: 4 }}>
          <span>المنتجات</span><span>{fmtMoney(total)}</span>
        </div>
        {deliveryFee > 0 && (
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, opacity: 0.75, marginBottom: 4 }}>
            <span>التوصيل</span><span>{fmtMoney(deliveryFee)}</span>
          </div>
        )}
        <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 800 }}>
          <span>الإجمالي</span><span style={{ color: C.green }}>{fmtMoney(grandTotal)}</span>
        </div>
      </div>
      <Btn onClick={submit} style={{ width: "100%" }} disabled={belowMin}>تأكيد الطلب</Btn>
    </Modal>
  );
}

/* ---------------- Admin Login Modal ---------------- */
/* ---------------- Review Modal ---------------- */
function ReviewModal({ onClose, onSubmit, currentUser }) {
  const [form, setForm] = useState({ name: currentUser?.name || "", rating: 5, comment: "" });
  const [err, setErr] = useState("");
  function submit() {
    if (!form.name || !form.comment) { setErr("اكتب اسمك وتقييمك من فضلك"); return; }
    onSubmit(form);
    onClose();
  }
  return (
    <Modal onClose={onClose} width={380}>
      <div style={{ fontWeight: 800, fontSize: 18, marginBottom: 16 }}>قيّم تجربتك معانا</div>
      <div style={{ marginBottom: 14 }}>
        <span style={{ fontSize: 13, opacity: 0.75, display: "block", marginBottom: 6 }}>تقييمك</span>
        <StarRow value={form.rating} onChange={(n) => setForm({ ...form, rating: n })} size={26} />
      </div>
      <Field label="اسمك" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
      <TextAreaField label="رأيك فينا" value={form.comment} onChange={(e) => setForm({ ...form, comment: e.target.value })} placeholder="إيه اللي عجبك؟" />
      {err && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{err}</div>}
      <Btn onClick={submit} style={{ width: "100%" }}>إرسال التقييم</Btn>
    </Modal>
  );
}

/* ---------------- Event Request Modal ---------------- */
function EventRequestModal({ onClose, onSubmit }) {
  const [form, setForm] = useState({ name: "", phone: "", eventDate: "", guests: "", notes: "" });
  const [err, setErr] = useState("");
  function submit() {
    if (!form.name || !form.phone) { setErr("اكتب اسمك ورقم تليفونك من فضلك"); return; }
    if (!isValidPhone(form.phone)) { setErr("اكتب رقم موبايل مصري صحيح (01 وبعده 9 أرقام)"); return; }
    onSubmit(form);
  }
  return (
    <Modal onClose={onClose}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
        <PartyPopper size={22} color={C.orange} />
        <div style={{ fontWeight: 800, fontSize: 18 }}>اطلب تجهيزات مناسبة أو حفلة</div>
      </div>
      <Field label="الاسم" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
      <Field label="رقم التليفون" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="01xxxxxxxxx" />
      <Field label="تاريخ المناسبة" type="date" value={form.eventDate} onChange={(e) => setForm({ ...form, eventDate: e.target.value })} />
      <Field label="عدد الأفراد تقريبًا" type="number" value={form.guests} onChange={(e) => setForm({ ...form, guests: e.target.value })} placeholder="مثلاً 40" />
      <TextAreaField label="تفاصيل إضافية" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="نوع المناسبة، الأصناف المطلوبة، أي طلبات خاصة..." />
      {err && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{err}</div>}
      <Btn onClick={submit} style={{ width: "100%" }}>إرسال الطلب</Btn>
    </Modal>
  );
}

function AdminLoginModal({ onClose, adminPass, onSuccess }) {
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  function submit() {
    if (pass === adminPass) onSuccess();
    else setErr("الباسورد غلط");
  }
  return (
    <Modal onClose={onClose} width={340}>
      <div style={{ textAlign: "center", marginBottom: 16 }}>
        <div style={{ width: 50, height: 50, borderRadius: 999, background: C.sage, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 10px" }}>
          <Lock size={22} color={C.green} />
        </div>
        <div style={{ fontWeight: 800, fontSize: 16 }}>دخول لوحة التحكم</div>
      </div>
      <Field label="الباسورد" type="password" value={pass} onChange={(e) => setPass(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} placeholder="********" />
      {err && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{err}</div>}
      <Btn onClick={submit} style={{ width: "100%" }}>دخول</Btn>
    </Modal>
  );
}

/* ================= ADMIN APP ================= */
function AdminApp(props) {
  const {
    settings, saveSettings, about, saveAbout, branch, saveBranch,
    products, saveProducts, bazaar, saveBazaar,
    orders, updateOrderStatus, deleteOrder, clearCompleted,
    categories, saveCategories, deliveryAreas, saveDeliveryAreas,
    reviews, saveReviews, eventRequests, saveEventRequests,
    news, saveNews, policies, savePolicies,
    adminPass, saveAdminPass, adminTab, setAdminTab, notifOn, setNotifOn, onExit, showToast,
  } = props;

  const pendingReviews = reviews.filter((r) => r.status === "pending").length;
  const newEvents = eventRequests.filter((e) => e.status === "جديد").length;

  const tabs = [
    ["orders", "الأوردرات", <Bell size={15} key="i" />],
    ["products", "المنتجات", <Package size={15} key="i" />],
    ["categories", "التصنيفات", <Tag size={15} key="i" />],
    ["delivery", "التوصيل", <Truck size={15} key="i" />],
    ["reviews", "التقييمات", <Star size={15} key="i" />],
    ["events", "المناسبات", <PartyPopper size={15} key="i" />],
    ["news", "الأخبار", <MessageSquarePlus size={15} key="i" />],
    ["home", "الصفحة الرئيسية", <Pencil size={15} key="i" />],
    ["bazaar", "البازارات", <ImageIcon size={15} key="i" />],
    ["policies", "السياسات", <FileText size={15} key="i" />],
    ["settings", "الإعدادات", <ShieldCheck size={15} key="i" />],
  ];
  const newCount = orders.filter((o) => o.status === "جديد").length;

  return (
    <div dir="rtl" style={{ fontFamily: "'Cairo','Tahoma',sans-serif", minHeight: "100%", background: C.ivory, color: C.ink }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Changa:wght@500;600;700;800&family=Cairo:wght@300;400;600;700;800;900&display=swap'); *{box-sizing:border-box}`}</style>
      <div style={{ background: C.greenDark, color: "#fff", padding: "14px 18px", display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <RingBadge src={LOGO} size={38} />
          <div style={{ fontWeight: 800 }}>لوحة تحكم {settings.brandAr}</div>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          {newCount > 0 && (
            <span style={{ background: C.orange, padding: "5px 12px", borderRadius: 999, fontSize: 12, fontWeight: 800, animation: "pulseDot 1.6s infinite" }}>
              {newCount} طلب جديد
            </span>
          )}
          <Btn variant="ghost" onClick={onExit} style={{ color: C.ink }}><LogOut size={14} /> خروج</Btn>
        </div>
      </div>

      <div style={{ display: "flex", gap: 8, padding: "14px 18px", overflowX: "auto", borderBottom: `1px solid ${C.line}`, background: C.white }}>
        {tabs.map(([id, label, icon]) => {
          const badge =
            id === "orders" ? newCount :
            id === "reviews" ? pendingReviews :
            id === "events" ? newEvents : 0;
          return (
            <button key={id} onClick={() => setAdminTab(id)} style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 16px", borderRadius: 999, border: "none", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, fontSize: 13, whiteSpace: "nowrap", background: adminTab === id ? C.green : C.sage, color: adminTab === id ? "#fff" : C.ink }}>
              {icon} {label} {badge > 0 && <span style={{ background: C.orange, borderRadius: 999, fontSize: 10, padding: "1px 6px" }}>{badge}</span>}
            </button>
          );
        })}
      </div>

      <div style={{ maxWidth: 980, margin: "0 auto", padding: 20 }}>
        {adminTab === "orders" && (
          <OrdersTab orders={orders} updateOrderStatus={updateOrderStatus} deleteOrder={deleteOrder} clearCompleted={clearCompleted} notifOn={notifOn} setNotifOn={setNotifOn} showToast={showToast} />
        )}
        {adminTab === "products" && <ProductsTab products={products} saveProducts={saveProducts} categories={categories} />}
        {adminTab === "categories" && <CategoriesTab categories={categories} saveCategories={saveCategories} products={products} saveProducts={saveProducts} showToast={showToast} />}
        {adminTab === "delivery" && <DeliveryTab settings={settings} saveSettings={saveSettings} deliveryAreas={deliveryAreas} saveDeliveryAreas={saveDeliveryAreas} showToast={showToast} />}
        {adminTab === "reviews" && <ReviewsTab reviews={reviews} saveReviews={saveReviews} showToast={showToast} />}
        {adminTab === "events" && <EventsTab eventRequests={eventRequests} saveEventRequests={saveEventRequests} showToast={showToast} />}
        {adminTab === "news" && <NewsTab news={news} saveNews={saveNews} showToast={showToast} />}
        {adminTab === "home" && <HomeTab about={about} saveAbout={saveAbout} branch={branch} saveBranch={saveBranch} showToast={showToast} />}
        {adminTab === "bazaar" && <BazaarTab bazaar={bazaar} saveBazaar={saveBazaar} showToast={showToast} />}
        {adminTab === "policies" && <PoliciesTab policies={policies} savePolicies={savePolicies} showToast={showToast} />}
        {adminTab === "settings" && <SettingsTab settings={settings} saveSettings={saveSettings} adminPass={adminPass} saveAdminPass={saveAdminPass} showToast={showToast} />}
      </div>
    </div>
  );
}

function Card({ children, style }) {
  return <div style={{ background: C.white, border: `1px solid ${C.line}`, borderRadius: 16, padding: 18, ...style }}>{children}</div>;
}

function OrdersTab({ orders, updateOrderStatus, deleteOrder, notifOn, setNotifOn, showToast, clearCompleted }) {
  const doneCount = orders.filter((o) => o.status === "تم التسليم" || o.status === "ملغي").length;
  function enableNotif() {
    if (!("Notification" in window)) { showToast("المتصفح ده مش بيدعم الإشعارات"); return; }
    Notification.requestPermission().then((p) => {
      if (p === "granted") { setNotifOn(true); showToast("تم تفعيل الإشعارات"); }
      else showToast("محتاج تسمح بالإشعارات من المتصفح");
    });
  }
  const statusColor = { "جديد": C.orange, "جاري التجهيز": "#3F7FBF", "تم التسليم": C.green, "ملغي": "#999" };
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16, flexWrap: "wrap", gap: 10 }}>
        <div style={{ fontWeight: 800, fontSize: 18 }}>الأوردرات ({orders.length})</div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {doneCount > 0 && (
            <Btn variant="danger" onClick={() => { if (window.confirm(`هتمسح ${doneCount} طلب (تم التسليم/ملغي). متأكد؟`)) clearCompleted(); }}>
              <Trash2 size={14} /> امسح المكتملة ({doneCount})
            </Btn>
          )}
          {!notifOn && (
            <Btn variant="ghost" onClick={enableNotif}><BellRing size={14} /> فعّل تنبيهات المتصفح</Btn>
          )}
        </div>
      </div>
      {orders.length === 0 ? (
        <Card style={{ textAlign: "center", padding: 40, opacity: 0.6 }}>لسه معندكش أي أوردرات</Card>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {orders.map((o) => (
            <Card key={o.id}>
              <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 10, marginBottom: 10 }}>
                <div>
                  <div style={{ fontWeight: 800 }}>{o.name} — {o.phone}</div>
                  <div style={{ fontSize: 12, opacity: 0.6 }}>{new Date(o.time).toLocaleString("ar-EG")}</div>
                </div>
                <span style={{ background: statusColor[o.status] || C.sage, color: "#fff", padding: "4px 12px", borderRadius: 999, fontSize: 12, fontWeight: 800, height: "fit-content" }}>{o.status}</span>
              </div>
              <div style={{ fontSize: 13, marginBottom: 8 }}><MapPin size={12} style={{ display: "inline" }} /> {o.address}{o.area ? ` — ${o.area}` : ""}</div>
              {o.notes && <div style={{ fontSize: 12, opacity: 0.7, marginBottom: 8 }}>ملاحظات: {o.notes}</div>}
              <div style={{ borderTop: `1px solid ${C.line}`, paddingTop: 8, display: "flex", flexDirection: "column", gap: 4 }}>
                {o.items.map((it, idx) => (
                  <div key={idx} style={{ display: "flex", justifyContent: "space-between", fontSize: 13 }}>
                    <span>{it.name} × {it.qty}</span><span>{fmtMoney(it.price * it.qty)}</span>
                  </div>
                ))}
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 10, flexWrap: "wrap", gap: 10 }}>
                <span style={{ fontWeight: 800, color: C.green }}>الإجمالي: {fmtMoney(o.total)}</span>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  <select value={o.status} onChange={(e) => updateOrderStatus(o.id, e.target.value)} style={{ borderRadius: 8, padding: "6px 10px", border: `1px solid ${C.line}`, fontFamily: "inherit", fontSize: 12 }}>
                    {["جديد", "جاري التجهيز", "تم التسليم", "ملغي"].map((s) => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <a href={`tel:${o.phone}`} style={{ display: "flex", alignItems: "center", gap: 4, background: C.sage, borderRadius: 8, padding: "6px 10px", fontSize: 12, textDecoration: "none", color: C.ink }}><Phone size={12} /> اتصال</a>
                  <button onClick={() => deleteOrder(o.id)} style={{ background: "#FBEAEA", border: "none", borderRadius: 8, padding: "6px 10px", cursor: "pointer" }}><Trash2 size={13} color="#C24A3A" /></button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function ImgUpload({ value, onChange }) {
  const ref = useRef();
  function handle(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => onChange(reader.result);
    reader.readAsDataURL(file);
  }
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
      <div style={{ width: 60, height: 60, borderRadius: 10, background: C.sage, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
        {value ? <img src={value} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <ImageIcon size={20} color={C.leaf} />}
      </div>
      <input ref={ref} type="file" accept="image/*" onChange={handle} style={{ display: "none" }} />
      <Btn variant="ghost" type="button" onClick={() => ref.current.click()}>اختار صورة</Btn>
      {value && <button type="button" onClick={() => onChange("")} style={{ background: "none", border: "none", cursor: "pointer", opacity: 0.6 }}><Trash2 size={15} /></button>}
    </div>
  );
}

function ProductsTab({ products, saveProducts, categories }) {
  const empty = { name: "", price: "", desc: "", image: "", categoryId: "", bestSeller: false, outOfStock: false };
  const [form, setForm] = useState(empty);
  const [editId, setEditId] = useState(null);
  const flatCats = flattenCategories(categories);

  function startEdit(p) { setEditId(p.id); setForm({ ...empty, ...p }); }
  function cancel() { setEditId(null); setForm(empty); }

  async function save() {
    if (!form.name || !form.price) return;
    if (editId) {
      await saveProducts(products.map((p) => (p.id === editId ? { ...form, id: editId, price: Number(form.price) } : p)));
    } else {
      await saveProducts([...products, { ...form, id: uid(), price: Number(form.price) }]);
    }
    cancel();
  }
  async function remove(id) {
    await saveProducts(products.filter((p) => p.id !== id));
  }
  function catName(id) {
    const c = categories.find((c) => c.id === id);
    return c ? c.name : "";
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr", gap: 20 }} className="admin-grid">
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>{editId ? "تعديل منتج" : "إضافة منتج جديد"}</div>
        <ImgUpload value={form.image} onChange={(v) => setForm({ ...form, image: v })} />
        <div style={{ marginTop: 12 }}>
          <Field label="اسم المنتج" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
          <Field label="السعر (جنيه)" type="number" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} />
          <label style={{ display: "block", marginBottom: 12 }}>
            <span style={{ fontSize: 13, color: C.ink, opacity: 0.75, display: "block", marginBottom: 5 }}>التصنيف (اختياري)</span>
            <select value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })} style={{ width: "100%", border: `1.5px solid ${C.line}`, borderRadius: 10, padding: "10px 12px", fontSize: 14, fontFamily: "inherit", background: C.white }}>
              <option value="">بدون تصنيف</option>
              {flatCats.map((c) => (
                <option key={c.id} value={c.id}>{"— ".repeat(c.depth) + c.name}</option>
              ))}
            </select>
          </label>
          <TextAreaField label="الوصف (اختياري)" value={form.desc} onChange={(e) => setForm({ ...form, desc: e.target.value })} />
          <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, cursor: "pointer", fontSize: 13, fontWeight: 700 }}>
            <input type="checkbox" checked={!!form.bestSeller} onChange={(e) => setForm({ ...form, bestSeller: e.target.checked })} />
            <Flame size={14} color={C.orange} /> منتج الأكثر مبيعًا (يظهر في قسم مخصص فوق المنتجات)
          </label>
          <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, cursor: "pointer", fontSize: 13, fontWeight: 700 }}>
            <input type="checkbox" checked={!!form.outOfStock} onChange={(e) => setForm({ ...form, outOfStock: e.target.checked })} />
            نفذت الكمية (هيتحجب زرار الطلب مؤقتًا)
          </label>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <Btn onClick={save} style={{ flex: 1 }}>{editId ? "حفظ التعديل" : "إضافة"}</Btn>
          {editId && <Btn variant="ghost" onClick={cancel}>إلغاء</Btn>}
        </div>
      </Card>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {products.length === 0 && <Card style={{ textAlign: "center", opacity: 0.6 }}>لسه مفيش منتجات مضافة</Card>}
        {products.map((p) => (
          <Card key={p.id} style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ width: 46, height: 46, borderRadius: 10, background: C.sage, overflow: "hidden", flexShrink: 0 }}>
              {p.image && <img src={p.image} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />}
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
                {p.name}
                {p.bestSeller && <Flame size={13} color={C.orange} />}
                {p.outOfStock && <span style={{ fontSize: 10, background: "#FBEAEA", color: "#C24A3A", padding: "2px 8px", borderRadius: 999, fontWeight: 700 }}>خلص</span>}
              </div>
              <div style={{ fontSize: 12, color: C.green, fontWeight: 700 }}>{fmtMoney(p.price)}</div>
              {p.categoryId && <div style={{ fontSize: 11, opacity: 0.6 }}>{catName(p.categoryId)}</div>}
            </div>
            <button
              title="اكثر مبيعًا"
              onClick={() => saveProducts(products.map((x) => (x.id === p.id ? { ...x, bestSeller: !x.bestSeller } : x)))}
              style={{ background: p.bestSeller ? C.orange : C.sage, border: "none", borderRadius: 8, padding: 8, cursor: "pointer" }}
            ><Flame size={14} color={p.bestSeller ? "#fff" : C.ink} /></button>
            <button
              title="نفذت الكمية"
              onClick={() => saveProducts(products.map((x) => (x.id === p.id ? { ...x, outOfStock: !x.outOfStock } : x)))}
              style={{ background: p.outOfStock ? "#C24A3A" : C.sage, border: "none", borderRadius: 8, padding: "8px 10px", cursor: "pointer", fontSize: 11, fontWeight: 700, color: p.outOfStock ? "#fff" : C.ink }}
            >خلصت</button>
            <button onClick={() => startEdit(p)} style={{ background: C.sage, border: "none", borderRadius: 8, padding: 8, cursor: "pointer" }}><Pencil size={14} /></button>
            <button onClick={() => remove(p.id)} style={{ background: "#FBEAEA", border: "none", borderRadius: 8, padding: 8, cursor: "pointer" }}><Trash2 size={14} color="#C24A3A" /></button>
          </Card>
        ))}
      </div>
      <style>{`@media (max-width:820px){.admin-grid{grid-template-columns:1fr !important}}`}</style>
    </div>
  );
}

/* ---------------- Categories Tab ---------------- */
function CategoriesTab({ categories, saveCategories, products, saveProducts, showToast }) {
  const [name, setName] = useState("");
  const [parentId, setParentId] = useState("");
  const flatCats = flattenCategories(categories);

  async function add() {
    if (!name.trim()) return;
    const item = { id: uid(), name: name.trim(), parentId: parentId || null };
    await saveCategories([...categories, item]);
    setName("");
    setParentId("");
  }
  async function remove(id) {
    const toRemove = [id, ...categoryDescendantIds(categories, id)];
    const updatedCats = categories.filter((c) => !toRemove.includes(c.id));
    const updatedProducts = products.map((p) => (toRemove.includes(p.categoryId) ? { ...p, categoryId: "" } : p));
    await saveCategories(updatedCats);
    if (updatedProducts !== products) await saveProducts(updatedProducts);
    showToast("تم حذف التصنيف");
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr", gap: 20 }} className="admin-grid">
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>إضافة تصنيف</div>
        <Field label="اسم التصنيف" value={name} onChange={(e) => setName(e.target.value)} placeholder="مثلاً: كفتة ومحاشي" />
        <label style={{ display: "block", marginBottom: 12 }}>
          <span style={{ fontSize: 13, color: C.ink, opacity: 0.75, display: "block", marginBottom: 5 }}>حط جوه تصنيف تاني؟ (اختياري)</span>
          <select value={parentId} onChange={(e) => setParentId(e.target.value)} style={{ width: "100%", border: `1.5px solid ${C.line}`, borderRadius: 10, padding: "10px 12px", fontSize: 14, fontFamily: "inherit", background: C.white }}>
            <option value="">تصنيف رئيسي</option>
            {flatCats.map((c) => (
              <option key={c.id} value={c.id}>{"— ".repeat(c.depth) + c.name}</option>
            ))}
          </select>
        </label>
        <Btn onClick={add} style={{ width: "100%" }}>إضافة التصنيف</Btn>
        <div style={{ fontSize: 11, opacity: 0.6, marginTop: 10, lineHeight: 1.7 }}>
          تقدر تحط تصنيف جوه تصنيف تاني (زي "أطباق حفلات" جوه "المناسبات") بقد ما تحب.
        </div>
      </Card>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {flatCats.length === 0 && <Card style={{ textAlign: "center", opacity: 0.6 }}>لسه مفيش تصنيفات</Card>}
        {flatCats.map((c) => (
          <Card key={c.id} style={{ display: "flex", alignItems: "center", gap: 10, marginRight: c.depth * 24 }}>
            <Tag size={15} color={C.leaf} />
            <div style={{ flex: 1, fontWeight: 700 }}>{c.name}</div>
            <button onClick={() => remove(c.id)} style={{ background: "#FBEAEA", border: "none", borderRadius: 8, padding: 8, cursor: "pointer" }}><Trash2 size={14} color="#C24A3A" /></button>
          </Card>
        ))}
      </div>
      <style>{`@media (max-width:820px){.admin-grid{grid-template-columns:1fr !important}}`}</style>
    </div>
  );
}

/* ---------------- Delivery Tab ---------------- */
function DeliveryTab({ settings, saveSettings, deliveryAreas, saveDeliveryAreas, showToast }) {
  const [minOrder, setMinOrder] = useState(settings.minOrder || "");
  const [areaName, setAreaName] = useState("");
  const [areaPrice, setAreaPrice] = useState("");

  async function saveMin() {
    await saveSettings({ ...settings, minOrder });
    showToast("تم الحفظ");
  }
  async function addArea() {
    if (!areaName.trim()) return;
    const item = { id: uid(), name: areaName.trim(), price: areaPrice === "" ? 0 : Number(areaPrice) };
    await saveDeliveryAreas([...deliveryAreas, item]);
    setAreaName("");
    setAreaPrice("");
  }
  async function updatePrice(id, price) {
    await saveDeliveryAreas(deliveryAreas.map((a) => (a.id === id ? { ...a, price: price === "" ? 0 : Number(price) } : a)));
  }
  async function removeArea(id) {
    await saveDeliveryAreas(deliveryAreas.filter((a) => a.id !== id));
  }

  return (
    <div style={{ display: "grid", gap: 20 }}>
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 10 }}>الحد الأدنى للطلب</div>
        <Field label="أقل مبلغ للطلب (جنيه) — اسيبه فاضي لو مفيش حد أدنى" type="number" value={minOrder} onChange={(e) => setMinOrder(e.target.value)} placeholder="مثلاً 150" />
        <Btn onClick={saveMin}>حفظ</Btn>
      </Card>
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>مناطق التوصيل وأسعارها</div>
        <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
          <div style={{ flex: 2, minWidth: 150 }}>
            <Field label="اسم المنطقة" value={areaName} onChange={(e) => setAreaName(e.target.value)} placeholder="مثلاً مدينة نصر" />
          </div>
          <div style={{ flex: 1, minWidth: 110 }}>
            <Field label="سعر التوصيل (اختياري)" type="number" value={areaPrice} onChange={(e) => setAreaPrice(e.target.value)} placeholder="حدده بعدين" />
          </div>
        </div>
        <Btn onClick={addArea} style={{ width: "100%", marginBottom: 16 }}>إضافة منطقة</Btn>
        {deliveryAreas.length === 0 && <div style={{ textAlign: "center", opacity: 0.6, padding: 20 }}>لسه مفيش مناطق مضافة</div>}
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {deliveryAreas.map((a) => (
            <div key={a.id} style={{ display: "flex", alignItems: "center", gap: 10, border: `1px solid ${C.line}`, borderRadius: 10, padding: "8px 12px" }}>
              <Truck size={15} color={C.leaf} />
              <div style={{ flex: 1, fontWeight: 700 }}>{a.name}</div>
              <input
                type="number" defaultValue={a.price} placeholder="السعر"
                onBlur={(e) => updatePrice(a.id, e.target.value)}
                style={{ width: 90, border: `1.5px solid ${C.line}`, borderRadius: 8, padding: "6px 8px", fontFamily: "inherit", fontSize: 13 }}
              />
              <span style={{ fontSize: 12, opacity: 0.6 }}>جنيه</span>
              <button onClick={() => removeArea(a.id)} style={{ background: "#FBEAEA", border: "none", borderRadius: 8, padding: 6, cursor: "pointer" }}><Trash2 size={13} color="#C24A3A" /></button>
            </div>
          ))}
        </div>
        <div style={{ fontSize: 11, opacity: 0.6, marginTop: 12 }}>لو السعر لسه مش متحدد، سيبه صفر وعدّله في أي وقت — العميل هيشوف اسم المنطقة بس.</div>
      </Card>
    </div>
  );
}

/* ---------------- Reviews Tab ---------------- */
function ReviewsTab({ reviews, saveReviews, showToast }) {
  async function approve(id) {
    await saveReviews(reviews.map((r) => (r.id === id ? { ...r, status: "approved" } : r)));
    showToast("تم نشر التقييم");
  }
  async function hide(id) {
    await saveReviews(reviews.map((r) => (r.id === id ? { ...r, status: "pending" } : r)));
  }
  async function remove(id) {
    await saveReviews(reviews.filter((r) => r.id !== id));
  }
  const pending = reviews.filter((r) => r.status === "pending");
  const approved = reviews.filter((r) => r.status === "approved");

  function ReviewRow({ r }) {
    return (
      <Card style={{ marginBottom: 10 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <div style={{ fontWeight: 800 }}>{r.name}</div>
          <div style={{ display: "flex" }}>
            {[1, 2, 3, 4, 5].map((n) => <Star key={n} size={14} fill={n <= r.rating ? C.orange : "none"} color={C.orange} />)}
          </div>
        </div>
        <div style={{ fontSize: 13, opacity: 0.8, marginBottom: 10 }}>{r.comment}</div>
        <div style={{ display: "flex", gap: 8 }}>
          {r.status === "pending" ? (
            <Btn onClick={() => approve(r.id)}><Check size={13} /> انشر</Btn>
          ) : (
            <Btn variant="ghost" onClick={() => hide(r.id)}>اخفي</Btn>
          )}
          <Btn variant="danger" onClick={() => remove(r.id)}><Trash2 size={13} /> امسح</Btn>
        </div>
      </Card>
    );
  }

  return (
    <div style={{ display: "grid", gap: 20 }}>
      <div>
        <div style={{ fontWeight: 800, marginBottom: 10 }}>في انتظار المراجعة ({pending.length})</div>
        {pending.length === 0 ? <Card style={{ textAlign: "center", opacity: 0.6 }}>لا يوجد تقييمات جديدة</Card> : pending.map((r) => <ReviewRow key={r.id} r={r} />)}
      </div>
      <div>
        <div style={{ fontWeight: 800, marginBottom: 10 }}>منشورة على الموقع ({approved.length})</div>
        {approved.length === 0 ? <Card style={{ textAlign: "center", opacity: 0.6 }}>لا يوجد تقييمات منشورة بعد</Card> : approved.map((r) => <ReviewRow key={r.id} r={r} />)}
      </div>
    </div>
  );
}

