function BazaarTab({ bazaar, saveBazaar, showToast }) {
  const empty = { type: "image", url: "", caption: "" };
  const [form, setForm] = useState(empty);
  const ref = useRef();
  const videoRef = useRef();

  function handleUpload(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setForm({ ...form, url: reader.result });
    reader.readAsDataURL(file);
  }
  function handleVideoUpload(e) {
    const file = e.target.files[0];
    if (!file) return;
    const MAX_MB = 3;
    if (file.size > MAX_MB * 1024 * 1024) {
      showToast(`الفيديو أكبر من ${MAX_MB} ميجا — استخدم رابط يوتيوب/فيسبوك بدل الرفع المباشر`);
      return;
    }
    const reader = new FileReader();
    reader.onload = () => setForm({ ...form, url: reader.result });
    reader.readAsDataURL(file);
  }
  async function add() {
    if (!form.url) return;
    await saveBazaar([...bazaar, { ...form, id: uid() }]);
    setForm(empty);
  }
  async function remove(id) {
    await saveBazaar(bazaar.filter((b) => b.id !== id));
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr", gap: 20 }} className="admin-grid">
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>إضافة صورة / فيديو</div>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <button onClick={() => setForm({ ...form, type: "image", url: "" })} style={{ flex: 1, padding: 8, borderRadius: 10, border: "none", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, background: form.type === "image" ? C.green : C.sage, color: form.type === "image" ? "#fff" : C.ink }}>صورة</button>
          <button onClick={() => setForm({ ...form, type: "video", url: "" })} style={{ flex: 1, padding: 8, borderRadius: 10, border: "none", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, background: form.type === "video" ? C.green : C.sage, color: form.type === "video" ? "#fff" : C.ink }}>فيديو</button>
        </div>
        {form.type === "image" ? (
          <div style={{ marginBottom: 12 }}>
            <input ref={ref} type="file" accept="image/*" onChange={handleUpload} style={{ display: "none" }} />
            <Btn variant="ghost" type="button" onClick={() => ref.current.click()} style={{ width: "100%", marginBottom: 8 }}>ارفع صورة من جهازك</Btn>
            <Field label="أو حط رابط صورة" value={form.url.startsWith("data:") ? "" : form.url} onChange={(e) => setForm({ ...form, url: e.target.value })} placeholder="https://..." />
          </div>
        ) : (
          <div style={{ marginBottom: 12 }}>
            <input ref={videoRef} type="file" accept="video/*" onChange={handleVideoUpload} style={{ display: "none" }} />
            <Btn variant="ghost" type="button" onClick={() => videoRef.current.click()} style={{ width: "100%", marginBottom: 6 }}>ارفع فيديو قصير من جهازك (لغاية 3 ميجا)</Btn>
            <div style={{ fontSize: 11, opacity: 0.6, marginBottom: 10, lineHeight: 1.7 }}>
              الفيديوهات بتاخد مساحة تخزين كبيرة، فالرفع المباشر متاح بس للفيديوهات الصغيرة جدًا (لغاية 3 ميجا تقريبًا). لأي فيديو أطول أو أعلى جودة، الأفضل ترفعه على يوتيوب/فيسبوك/تيك توك وتحط الرابط هنا — هيتعرض هنا زي الرفع بالظبط.
            </div>
            <Field label="أو حط رابط الفيديو (يوتيوب / mp4)" value={form.url.startsWith("data:") ? "" : form.url} onChange={(e) => setForm({ ...form, url: e.target.value })} placeholder="https://youtube.com/..." />
          </div>
        )}
        <Field label="تعليق (اختياري)" value={form.caption} onChange={(e) => setForm({ ...form, caption: e.target.value })} placeholder="بازار مدينتي مثلاً" />
        <Btn onClick={add} style={{ width: "100%" }}>إضافة</Btn>
      </Card>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 12, alignContent: "flex-start" }}>
        {bazaar.length === 0 && <Card style={{ width: "100%", textAlign: "center", opacity: 0.6 }}>لسه مفيش صور أو فيديوهات</Card>}
        {bazaar.map((item) => (
          <div key={item.id} style={{ width: 130, textAlign: "center" }}>
            <div style={{ width: 130, height: 130, borderRadius: 14, overflow: "hidden", border: `1px solid ${C.line}` }}>{renderMedia(item)}</div>
            <div style={{ fontSize: 11, marginTop: 6, opacity: 0.7 }}>{item.caption}</div>
            <button onClick={() => remove(item.id)} style={{ background: "#FBEAEA", border: "none", borderRadius: 8, padding: 6, cursor: "pointer", marginTop: 6 }}><Trash2 size={12} color="#C24A3A" /></button>
          </div>
        ))}
      </div>
      <style>{`@media (max-width:820px){.admin-grid{grid-template-columns:1fr !important}}`}</style>
    </div>
  );
}

function SettingsTab({ settings, saveSettings, adminPass, saveAdminPass, showToast }) {
  const [s, setS] = useState(settings);
  const [oldPass, setOldPass] = useState("");
  const [newPass, setNewPass] = useState("");
  const [passErr, setPassErr] = useState("");

  async function changePass() {
    if (oldPass !== adminPass) { setPassErr("الباسورد القديم غلط"); return; }
    if (newPass.length < 4) { setPassErr("الباسورد الجديد لازم 4 أرقام على الأقل"); return; }
    await saveAdminPass(newPass);
    setOldPass(""); setNewPass(""); setPassErr("");
    showToast("تم تغيير الباسورد");
  }

  return (
    <div style={{ display: "grid", gap: 20 }}>
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>بيانات التواصل والسوشيال ميديا</div>
        <Field label="رقم خدمة العملاء" value={s.phone} onChange={(e) => setS({ ...s, phone: e.target.value })} />
        <Field label="رقم الواتساب" value={s.whatsapp} onChange={(e) => setS({ ...s, whatsapp: e.target.value })} />
        <Field label="فيسبوك" value={s.facebook} onChange={(e) => setS({ ...s, facebook: e.target.value })} />
        <Field label="انستجرام" value={s.instagram} onChange={(e) => setS({ ...s, instagram: e.target.value })} />
        <Field label="تيك توك" value={s.tiktok} onChange={(e) => setS({ ...s, tiktok: e.target.value })} />
        <Btn onClick={() => { saveSettings(s); showToast("تم الحفظ"); }}>حفظ الإعدادات</Btn>
      </Card>
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>أرقام تظهر في آخر الصفحة</div>
        <Field label="سنين الخبرة (مثلاً +10)" value={s.experienceYears} onChange={(e) => setS({ ...s, experienceYears: e.target.value })} />
        <Field label="عدد الأوردرات (مثلاً +11000)" value={s.ordersCount} onChange={(e) => setS({ ...s, ordersCount: e.target.value })} />
        <Btn onClick={() => { saveSettings(s); showToast("تم الحفظ"); }}>حفظ</Btn>
      </Card>
      <Card>
        <div style={{ fontWeight: 800, marginBottom: 12 }}>تغيير باسورد لوحة التحكم</div>
        <Field label="الباسورد القديم" type="password" value={oldPass} onChange={(e) => setOldPass(e.target.value)} />
        <Field label="الباسورد الجديد" type="password" value={newPass} onChange={(e) => setNewPass(e.target.value)} />
        {passErr && <div style={{ color: "#C24A3A", fontSize: 13, marginBottom: 10 }}>{passErr}</div>}
        <Btn onClick={changePass}>تغيير الباسورد</Btn>
      </Card>
    </div>
  );
}
